import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {test} from 'node:test';
import {analyzeXAccount, projectXAccountReport} from '../server/research/x-account-analysis.js';
import {DshProtocolRepairExhaustedError} from '../server/research/dsh-decision.js';
import type {XAccountAnalysisInput,XAccountModel,XAccountResearchState,XAccountPost} from '../server/research/x-account-contracts.js';
import type {SourceDraft} from '../shared/types.js';
const hash=(text:string)=>createHash('sha256').update(text).digest('hex');
function fixture(count=1,automaticOrganization:boolean|number=true,automaticSelection=true):XAccountAnalysisInput {
 const subject={nativeId:'acct-1',handle:'synthetic',name:'Synthetic',description:'',url:'https://x.com/synthetic'};
 const posts:XAccountPost[]=Array.from({length:count},(_,i)=>({id:String(i),url:`https://x.com/synthetic/status/${i}`,authorId:'acct-1',authorHandle:'synthetic',text:`I built the synthetic tool ${i} to compare reading notes.`,publishedAt:`2025-01-${String((i%28)+1).padStart(2,'0')}T00:00:00Z`,kind:'original',parentId:null,quotedId:null,conversationId:null,replyCount:0,textField:'full_text',truncated:false,sourceKey:`post-${i}`,role:'target',rootIds:[]}));
 const history=()=>({started:true,cursor:null,done:true,pages:2,cursors:[],pageHashes:[]});
 const state:XAccountResearchState={version:'x-account/v1',accountId:'selected',profile:subject,history:{timeline:history(),replies:history()},posts,contextQueue:[],contextDone:[],gaps:[],analysis:{completedBatches:[],findings:[],synthesisDone:false}};
 const input:XAccountAnalysisInput={subject,question:'分析这个账号的作品',posts,state,pages:posts.map(p=>({sourceKey:p.sourceKey,url:p.url,title:p.id,text:p.text,kind:'work',publishedAt:p.publishedAt,links:[],limitations:[],author:p.authorHandle,retrieval:'read',textTruncated:false})),model:async()=>({findings:[]}),signal:new AbortController().signal,save:()=>{},active:()=>{}};
 let port=input.model;Object.defineProperty(input,'model',{get:()=>async(request:Parameters<XAccountModel>[0],signal:AbortSignal)=>{
  const data=dataOf(request.prompt);if(automaticSelection&&data.reportStage==='select'){let used=0;const ids:string[]=[];for(const item of data.items){if(used+item.materialChars<=data.materialBudgetChars&&(data.maximumSelected===null||ids.length<data.maximumSelected)){ids.push(item.id);used+=item.materialChars;}}return{ids};}if(typeof automaticOrganization==='number'&&data.organizationStage){const buckets=new Map<number,string[]>();data.items.forEach((item:{id:string},i:number)=>{const k=data.organizationStage==='index'?i%automaticOrganization:i;const ids=buckets.get(k)??[];ids.push(item.id);buckets.set(k,ids);});return{groups:[...buckets].map(([i,ids])=>({section:'work',title:`专题${i}`,ids}))};}if(automaticOrganization&&data.organizationStage){const groups=new Map<string,string[]>();for(const item of data.items){const ids=groups.get(item.section)??[];ids.push(item.id);groups.set(item.section,ids);}return{groups:[...groups].map(([section,ids])=>({section,title:section,ids}))};}return port(request,signal);
 },set:(next:XAccountModel)=>{port=next;}});return input;
}
function sources(input:XAccountAnalysisInput):SourceDraft[]{return input.pages.map(p=>({key:p.sourceKey,url:p.url,title:p.title,kind:p.kind,publishedAt:p.publishedAt,excerpt:p.text,excerptLocator:null,identityLabel:'账号原文',identityConfirmed:false,fetchStatus:'ok',limits:[]}));}
const output=(key='post-0')=>({section:'work',statement:'该账号自述制作了用于比较阅读笔记的工具。',kind:'attributed_statement',evidence:[{sourceKey:key,quote:'I built the synthetic tool',quoteOffset:0}],verified:true});
const dataOf=(prompt:string)=>JSON.parse(prompt.slice(prompt.indexOf('\nDATA\n')+6));
async function until(predicate:()=>boolean):Promise<void>{for(let i=0;i<100&&!predicate();i++)await new Promise<void>(resolve=>setImmediate(resolve));assert.ok(predicate(),'expected phase did not start');}
function acceptModel():XAccountModel{return async ({purpose,prompt})=>{const data=dataOf(prompt);if(purpose.includes('verify'))return {verdicts:data.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'原文支持账号自述。'}))};return {findings:[output(data.materials[0]!.sourceKey)]};};}
test('binds original quote and hash; projects independently verified Chinese statement',async()=>{
 const input=fixture();input.model=acceptModel();await analyzeXAccount(input);assert.equal(input.state.analysis.synthesisDone,true);
 const result=projectXAccountReport({state:input.state,pages:input.pages,sources:sources(input),activeSourceKeys:new Set(['post-0'])});assert.equal(result.observations.length,1);assert.equal(result.answer[0]!.bullets[0]!.text,result.observations[0]!.statement);assert.equal(result.findings[0]!.evidence[0]!.sourceContentHash,hash(input.pages[0]!.text));assert.deepEqual(result.observations[0]!.sourceKeys,['post-0']);assert.match(result.limitations.join(' '),/不代表.*全部历史/);
});
test('resume preserves exact findings without repeating model calls',async()=>{const input=fixture();input.model=acceptModel();await analyzeXAccount(input);const persisted=JSON.stringify(input.state.analysis);input.model=async()=>{throw Error('replayed model call');};await analyzeXAccount(input);assert.equal(JSON.stringify(input.state.analysis),persisted);});
test('all retained posts beyond preview enter bounded batches',async()=>{const input=fixture(75);const seen=new Set<string>();input.model=async({purpose,prompt})=>{assert.ok(prompt.length<65000);if(purpose==='x-account-analyze')for(const m of dataOf(prompt).materials)seen.add(m.sourceKey);return {findings:[]};};await analyzeXAccount(input);assert.equal(seen.size,75);assert.equal(input.state.analysis.synthesisDone,false);});
test('model verified flag cannot bypass independent rejection',async()=>{const input=fixture();input.model=async({purpose,prompt})=>purpose.includes('verify')?{verdicts:dataOf(prompt).findings.map((f:{id:string})=>({id:f.id,supported:false,reason:'原文不支持。'}))}:{findings:[output()]};await analyzeXAccount(input);assert.equal(input.state.analysis.findings.filter(f=>f.verified).length,0);});
test('verifier must partition every id without missing or invented ids',async()=>{for(const verdicts of [[],[{id:'invented',supported:true,reason:'支持'}]]){const input=fixture();input.model=async({purpose})=>purpose.includes('verify')?{verdicts}:{findings:[output()]};await analyzeXAccount(input);assert.equal(input.state.analysis.findings.filter(f=>f.verified).length,0);assert.ok(input.state.gaps.some(g=>g.code==='analysis_batch_protocol_unverified'));assert.equal(input.state.analysis.synthesisDone,false);}});
test('invalid quote, unknown source, English prose, truncation, repost and third-party work attribution fail closed',async()=>{for(const scenario of ['quote','foreign','english','truncated','repost','context']){const input=fixture();const finding=output();if(scenario==='quote')finding.evidence[0]!.quote='invented';if(scenario==='foreign')finding.evidence[0]!.sourceKey='outside';if(scenario==='english')finding.statement='This person is an expert creator.';if(scenario==='truncated')input.posts[0]!.truncated=true;if(scenario==='repost')input.posts[0]!.kind='repost';if(scenario==='context'){input.posts[0]!.role='quoted_context';input.posts[0]!.authorId='other';}input.model=async({purpose})=>{assert.ok(!purpose.includes('verify'));return {findings:[finding]};};await analyzeXAccount(input);assert.equal(input.state.analysis.findings.length,0,scenario);}});
test('revocation or stale page/excerpt/hash invalidates the entire dependent finding',()=>{for(const scenario of ['revoked','page','excerpt','hash']){const input=fixture(2);input.state.analysis.findings=[{id:'synthesis:test',section:'themes',statement:'该账号的两篇帖子都提到比较阅读笔记的工具。',kind:'inference',verified:true,evidence:input.pages.map(p=>({sourceKey:p.sourceKey,quote:'I built the synthetic tool',quoteOffset:0,sourceContentHash:hash(p.text)}))}];const src=sources(input);const active=new Set(['post-0','post-1']);if(scenario==='revoked')active.delete('post-1');if(scenario==='page')input.pages[1]!.text+=' changed';if(scenario==='excerpt')src[1]!.excerpt='changed';if(scenario==='hash')input.state.analysis.findings[0]!.evidence[1]!.sourceContentHash='old';const result=projectXAccountReport({state:input.state,pages:input.pages,sources:src,activeSourceKeys:active});assert.equal(result.observations.length,0,scenario);assert.match(result.limitations.join(' '),/待复核/);}});
test('trend inference requires multiple dated target originals',async()=>{const input=fixture();input.model=async()=>({findings:[{...output(),section:'changes',kind:'inference',statement:'该账号从早期关注工具转向了阅读研究。'}]});await analyzeXAccount(input);assert.equal(input.state.analysis.findings.length,0);});
test('cancellation after model call never persists its finding',async()=>{const input=fixture();const c=new AbortController();input.signal=c.signal;input.model=async()=>{c.abort();return {findings:[output()]};};await assert.rejects(analyzeXAccount(input));assert.equal(input.state.analysis.findings.length,0);});
test('native parent context accompanies its target reply even when stored on a distant page',async()=>{
 const input=fixture(50);input.posts[0]!.kind='reply';input.posts[0]!.parentId='49';input.posts[49]!.role='parent_context';input.posts[49]!.authorId='other-account';input.posts[49]!.authorHandle='other';input.posts[49]!.rootIds=['0'];let contextual=false;
 input.model=async({purpose,prompt})=>{if(purpose==='x-account-analyze'){const m=dataOf(prompt).materials;if(m.some((p:{sourceKey:string})=>p.sourceKey==='post-0'))contextual=m.some((p:{sourceKey:string;authorId:string;role:string})=>p.sourceKey==='post-49'&&p.authorId==='other-account'&&p.role==='parent_context');}return {findings:[]};};await analyzeXAccount(input);assert.equal(contextual,true);
});
test('final synthesis can discover a supported temporal change across earlier batch categories',async()=>{
 const input=fixture(2,false);input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(data.organizationStage)return{groups:[{section:'changes',title:'时间变化',ids:data.items.map((i:{id:string})=>i.id)}]};if(purpose.includes('verify'))return {verdicts:data.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'两个有日期的原文支持这一分析。'}))};if(purpose==='x-account-write')return {findings:[{...output(),section:'changes',kind:'inference',statement:'从这两篇有日期的帖子看，该账号继续制作阅读笔记工具。',evidence:[output('post-0').evidence[0],output('post-1').evidence[0]]}]};return {findings:[output('post-0'),output('post-1')]};};await analyzeXAccount(input);assert.ok(input.state.analysis.findings.some(f=>f.id.startsWith('report:')&&f.section==='changes'));
});
test('long post tail is analyzed and quoted using its original absolute offset',async()=>{
 const input=fixture();const tail='I built a second synthetic notebook.';input.posts[0]!.text='Long synthetic material. '.repeat(700)+tail;input.pages[0]!.text=input.posts[0]!.text;const offset=input.pages[0]!.text.indexOf(tail);let sawTail=false;
 input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(purpose.includes('verify'))return {verdicts:data.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'原文包含该自述。'}))};const found=data.materials.some((m:{text:string})=>m.text.includes(tail));if(purpose==='x-account-analyze'&&found)sawTail=true;return {findings:found?[{...output(),statement:'该账号自述又制作了一款笔记工具。',evidence:[{sourceKey:'post-0',quote:tail,quoteOffset:offset}]}]:[]};};await analyzeXAccount(input);assert.equal(sawTail,true);assert.ok(input.state.analysis.findings.some(f=>f.evidence.some(e=>e.quoteOffset===offset)));
});
test('final synthesis is independently rejected while candidate indices remain unverified',async()=>{
 const input=fixture();input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(purpose.includes('verify'))return {verdicts:data.findings.map((f:{id:string})=>({id:f.id,supported:purpose!=='x-account-verify-synthesis',reason:'独立检查这一阶段。'}))};return {findings:[output()]};};await analyzeXAccount(input);assert.ok(input.state.analysis.findings.some(f=>f.id.startsWith('batch:')));assert.ok(!input.state.analysis.findings.some(f=>f.id.startsWith('report:')));
 assert.equal(input.state.analysis.synthesisDone,false);
 assert.ok(input.state.gaps.some(g=>g.code==='analysis_report_unverified'));
 const report=projectXAccountReport({state:input.state,pages:input.pages,sources:sources(input),activeSourceKeys:new Set(['post-0'])});
 assert.equal(report.observations.length,0);assert.match(report.limitations.join(' '),/专题综合.*未.*独立核验/);
 let replayed=false;input.model=async()=>{replayed=true;throw Error('unexpected replay');};await analyzeXAccount(input);assert.equal(replayed,false);assert.equal(input.state.analysis.synthesisDone,false);
});
test('server derives unique literal quote offset when missing or miscounted across emoji and Chinese',async()=>{
 for(const supplied of [undefined,1]){const input=fixture();const quote='I built the synthetic tool';input.posts[0]!.text=`📝 中文前言。${quote} to compare notes.`;input.pages[0]!.text=input.posts[0]!.text;input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(purpose.includes('verify'))return {verdicts:data.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'原文支持这一自述。'}))};return {findings:[{...output(),evidence:[{sourceKey:'post-0',quote,...(supplied===undefined?{}:{quoteOffset:supplied})}]}]};};await analyzeXAccount(input);assert.ok(input.state.analysis.findings.length>0);for(const finding of input.state.analysis.findings)assert.equal(finding.evidence[0]!.quoteOffset,8);}
});
test('repeated literal quotes require a matching supplied absolute offset',async()=>{
 for(const supplied of [undefined,1,7]){const input=fixture();const quote='I built the synthetic tool';input.posts[0]!.text=`prefix ${quote}. Again: ${quote}.`;input.pages[0]!.text=input.posts[0]!.text;input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(purpose.includes('verify'))return {verdicts:data.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'原文支持这一自述。'}))};return {findings:[{...output(),evidence:[{sourceKey:'post-0',quote,...(supplied===undefined?{}:{quoteOffset:supplied})}]}]};};await analyzeXAccount(input);assert.equal(input.state.analysis.findings.length>0,supplied===7);}
});
test('withdrawn corpus guard prevents a model call and discards a response revoked in flight',async()=>{
 for(const timing of ['before','during']){const input=fixture();let withdrawn=timing==='before';let calls=0;input.active=()=>{if(withdrawn)throw Error('source withdrawn');};input.model=async()=>{calls++;withdrawn=true;return {findings:[output()]};};await assert.rejects(analyzeXAccount(input),/source withdrawn/);assert.equal(calls,timing==='before'?0:1);assert.equal(input.state.analysis.findings.length,0);}
});

test('synthesis repairs rejected semantics using original material and explicit feedback then independently verifies again',async()=>{
 const input=fixture();let syntheses=0;let repairsHaveEvidence=false;
 input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(purpose.includes('verify'))return {verdicts:data.findings.map((f:{id:string;statement:string})=>({id:f.id,supported:purpose!=='x-account-verify-synthesis'||f.statement.includes('据该账号自述'),reason:'应保留账号自述限定，不能写成独立证实的事实。'}))};if(purpose==='x-account-write'){syntheses++;if(syntheses>1)repairsHaveEvidence=data.materials[0].text===input.pages[0]!.text&&data.rejections.some((r:{reason:string})=>r.reason.includes('自述'));}return {findings:[syntheses>1?{...output(),statement:'据该账号自述，它制作了用于比较阅读笔记的工具。'}:output()]};};
 await analyzeXAccount(input);assert.equal(syntheses,2);assert.equal(repairsHaveEvidence,true);assert.equal(input.state.analysis.synthesisDone,true);assert.ok(input.state.analysis.findings.some(f=>f.id.startsWith('report:')));assert.ok(!input.state.gaps.some(g=>g.code==='analysis_synthesis_unverified'));
});
test('unrepairable synthesis stops after initial proposal and two regeneration attempts',async()=>{
 const input=fixture();let syntheses=0;input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(purpose.includes('verify'))return {verdicts:data.findings.map((f:{id:string})=>({id:f.id,supported:purpose!=='x-account-verify-synthesis',reason:'原文不足以支持综合结论。'}))};if(purpose==='x-account-write')syntheses++;return {findings:[output()]};};await analyzeXAccount(input);assert.equal(syntheses,3);assert.equal(input.state.analysis.synthesisDone,false);assert.equal(input.state.gaps.filter(g=>g.code==='analysis_report_unverified').length,1);
});
test('independent batches run at concurrency three without imposing a corpus sample cap',async()=>{
 const input=fixture(85);const releases:Array<()=>void>=[];const started:string[]=[];const seen=new Set<string>();let active=0;let peak=0;
 input.model=async({purpose,prompt})=>{assert.equal(purpose,'x-account-analyze');const materials=dataOf(prompt).materials as Array<{sourceKey:string}>;started.push(materials[0]!.sourceKey);for(const item of materials)seen.add(item.sourceKey);active++;peak=Math.max(peak,active);if(started.length<=3)await new Promise<void>(resolve=>releases.push(resolve));active--;return {findings:[]};};
 const running=analyzeXAccount(input);await new Promise<void>(resolve=>setImmediate(resolve));assert.equal(started.length,3);assert.equal(new Set(started).size,3);for(const release of releases)release();await running;assert.equal(peak,3);assert.equal(seen.size,85);assert.equal(input.state.analysis.completedBatches.filter(k=>k.startsWith('batch:')).length,5);
});
test('first batch failure stops new dispatch but waits for every in-flight worker before rejecting',async()=>{
 const input=fixture(85);const pending:Array<{resolve:()=>void;reject:(error:Error)=>void}>=[];let calls=0;let settled=false;let saves=0;input.save=()=>{saves++;};
 input.model=async()=>{calls++;await new Promise<void>((resolve,reject)=>pending.push({resolve,reject}));return {findings:[]};};
 const running=analyzeXAccount(input).then(()=>{settled=true;throw Error('unexpected success');},error=>{settled=true;return error as Error;});
 await new Promise<void>(resolve=>setImmediate(resolve));assert.equal(calls,3);pending[0]!.reject(Error('first provider failure'));await new Promise<void>(resolve=>setImmediate(resolve));assert.equal(settled,false);assert.equal(calls,3);
 pending[1]!.resolve();await new Promise<void>(resolve=>setImmediate(resolve));assert.equal(settled,false);assert.equal(calls,3);pending[2]!.resolve();assert.match((await running).message,/first provider failure/);assert.equal(calls,3);assert.equal(input.state.analysis.completedBatches.filter(k=>k.startsWith('batch:')).length,2);const finalSaves=saves;await new Promise<void>(resolve=>setImmediate(resolve));assert.equal(saves,finalSaves);
});
test('global report chunks run concurrently only after all candidate reading jobs finish',async()=>{
 const input=fixture(50,5);let active=0;let peak=0;let synthesisCalls=0;let batchVerdicts=0;const releases:Array<()=>void>=[];
 input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(purpose.includes('verify')){if(purpose==='x-account-verify-synthesis')batchVerdicts+=data.findings.length;return {verdicts:data.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'原文支持自述。'}))};}if(purpose==='x-account-analyze')return {findings:data.materials.map((m:{sourceKey:string})=>output(m.sourceKey))};assert.equal(purpose,'x-account-write');assert.equal(input.state.analysis.completedBatches.filter(k=>k.startsWith('batch:')).length,3);synthesisCalls++;active++;peak=Math.max(peak,active);if(synthesisCalls<=3)await new Promise<void>(resolve=>releases.push(resolve));active--;return {findings:[output(data.materials[0].sourceKey)]};};
 const running=analyzeXAccount(input);await until(()=>synthesisCalls===3);assert.equal(synthesisCalls,3);for(const release of releases)release();await running;assert.equal(peak,3);assert.equal(synthesisCalls,5);assert.equal(input.state.analysis.findings.filter(f=>f.id.startsWith('batch:')).length,50);assert.equal(input.state.analysis.findings.filter(f=>f.id.startsWith('report:')).length,5);assert.equal(input.state.analysis.synthesisDone,true);
});
test('failed synthesis drains concurrent proposals and verifications before returning with partial evidence',async()=>{
 const input=fixture(50,5);const pending:Array<{resolve:()=>void;reject:(error:Error)=>void}>=[];let synthesisCalls=0;let settled=false;let saves=0;input.save=()=>{saves++;};
 input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(purpose.includes('verify'))return {verdicts:data.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'原文支持自述。'}))};if(purpose==='x-account-analyze')return {findings:data.materials.map((m:{sourceKey:string})=>output(m.sourceKey))};synthesisCalls++;await new Promise<void>((resolve,reject)=>pending.push({resolve,reject}));return {findings:[output(data.materials[0].sourceKey)]};};
 const running=analyzeXAccount(input).then(()=>{settled=true;throw Error('unexpected success');},error=>{settled=true;return error as Error;});await until(()=>synthesisCalls===3);assert.equal(synthesisCalls,3);pending[0]!.reject(Error('synthesis unavailable'));await new Promise<void>(resolve=>setImmediate(resolve));assert.equal(settled,false);pending[1]!.resolve();pending[2]!.resolve();assert.match((await running).message,/synthesis unavailable/);assert.equal(synthesisCalls,3);assert.equal(input.state.analysis.findings.filter(f=>f.id.startsWith('report:')).length,2);assert.equal(input.state.analysis.synthesisDone,false);const finalSaves=saves;await new Promise<void>(resolve=>setImmediate(resolve));assert.equal(saves,finalSaves);
});
function overlappingContextFixture():XAccountAnalysisInput {
 const input=fixture(41);const context=input.posts[40]!;
 context.role='parent_context';context.authorId='other-account';context.authorHandle='other';context.rootIds=['0','20'];
 return input;
}
const overlappingContextFinding=()=>({...output('post-40'),section:'interaction',kind:'page_statement',statement:'other 在讨论中自述制作了用于比较阅读笔记的工具。'});
test('overlapping contextual indices deduplicate before one final report verification',async()=>{
 const input=overlappingContextFixture();let batchVerificationCalls=0;let release!:()=>void;const gate=new Promise<void>(resolve=>{release=resolve;});
 input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(purpose.includes('verify')){if(purpose==='x-account-verify-synthesis'){batchVerificationCalls++;await gate;}return {verdicts:data.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'原文支持这一账号自述。'}))};}return {findings:purpose==='x-account-analyze'&&data.mode==='baseline'?[]:[overlappingContextFinding()]};};
 const running=analyzeXAccount(input);await until(()=>batchVerificationCalls===1);assert.equal(batchVerificationCalls,1);release();await running;assert.equal(input.state.analysis.completedBatches.filter(k=>k.startsWith('batch:')).length,4);assert.equal(input.state.analysis.findings.filter(f=>f.id.startsWith('batch:')).length,1);assert.equal(input.state.analysis.synthesisDone,true);
});
test('coalesced rejected promise is removed so a later analysis attempt can call the port again',async()=>{
 const input=overlappingContextFixture();let batchVerificationCalls=0;let rejectGate!:(error:Error)=>void;let firstAttempt=true;const gate=new Promise<void>((_,reject)=>{rejectGate=reject;});
 input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(purpose.includes('verify')){if(purpose==='x-account-verify-synthesis'){batchVerificationCalls++;if(firstAttempt)await gate;}return {verdicts:data.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'原文支持这一账号自述。'}))};}return {findings:purpose==='x-account-analyze'&&data.mode==='baseline'?[]:[overlappingContextFinding()]};};
 const running=analyzeXAccount(input);const rejected=assert.rejects(running,/temporary model failure/);await until(()=>batchVerificationCalls===1);assert.equal(batchVerificationCalls,1);rejectGate(Error('temporary model failure'));await rejected;assert.equal(input.state.analysis.findings.filter(f=>f.verified).length,0);firstAttempt=false;await analyzeXAccount(input);assert.equal(batchVerificationCalls,2);assert.equal(input.state.analysis.synthesisDone,true);
});
test('verifier repairs an invented ID using explicit expected IDs and unchanged original evidence',async()=>{
 const input=fixture();let attempts=0;let firstMaterials='';let firstFindings='';
 input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(purpose.includes('verify')){if(purpose==='x-account-verify-synthesis'){attempts++;if(attempts===1){firstMaterials=JSON.stringify(data.materials);firstFindings=JSON.stringify(data.findings);return {verdicts:[{id:'copied-wrong-id',supported:true,reason:'原文支持自述。'}]};}assert.deepEqual(data.expectedIds,data.findings.map((f:{id:string})=>f.id));assert.equal(data.protocolAttempt,1);assert.deepEqual(data.partitionFeedback.inventedIds,['copied-wrong-id']);assert.deepEqual(data.partitionFeedback.missingIds,data.expectedIds);assert.equal(JSON.stringify(data.materials),firstMaterials);assert.equal(JSON.stringify(data.findings),firstFindings);}return {verdicts:data.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'原文支持自述。'}))};}return {findings:[output()]};};
 await analyzeXAccount(input);assert.equal(attempts,2);assert.equal(input.state.analysis.synthesisDone,true);assert.equal(input.state.analysis.findings.filter(f=>f.verified&&f.id.startsWith('report:')).length,1);
});
test('verifier protocol repair rejects three malformed partitions with a bounded number of calls',async()=>{
 const input=fixture();let attempts=0;const prompts=new Set<string>();input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(purpose.includes('verify')){attempts++;prompts.add(prompt);if(attempts===1)return {verdicts:[{id:data.findings[0].id,supported:'true',reason:''}]};if(attempts===2){assert.deepEqual(data.partitionFeedback.malformedIndexes,[0]);return {verdicts:[{id:data.findings[0].id,supported:true,reason:'支持'},{id:data.findings[0].id,supported:true,reason:'重复'}]};}assert.deepEqual(data.partitionFeedback.duplicateIds,[data.findings[0].id]);return {verdicts:[]};}return {findings:[output()]};};await analyzeXAccount(input);assert.ok(input.state.gaps.some(g=>g.code==='analysis_batch_protocol_unverified'));assert.equal(attempts,3);assert.equal(prompts.size,3);assert.equal(input.state.analysis.findings.filter(f=>f.verified).length,0);assert.equal(input.state.analysis.synthesisDone,false);
});
test('baseline target windows are processed once and context jobs repeat only roots with native links',async()=>{
 const input=fixture(26);for(let i=20;i<26;i++){input.posts[i]!.role='reply_context';input.posts[i]!.authorId='other';input.posts[i]!.authorHandle='other';input.posts[i]!.rootIds=['0'];input.posts[i]!.text='Synthetic contextual reply. '.repeat(230);input.pages[i]!.text=input.posts[i]!.text;}
 const exposure=new Map<string,number>();const contextExposure=new Map<string,number>();let baselineJobs=0;let contextJobs=0;
 input.model=async({purpose,prompt})=>{assert.equal(purpose,'x-account-analyze');const data=dataOf(prompt);if(data.mode==='baseline')baselineJobs++;else if(data.mode==='context'){contextJobs++;assert.deepEqual(data.materials.filter((m:{role:string})=>m.role==='target').map((m:{sourceKey:string})=>m.sourceKey),['post-0']);}for(const m of data.materials){exposure.set(m.sourceKey,(exposure.get(m.sourceKey)??0)+1);if(m.role!=='target')contextExposure.set(m.sourceKey,(contextExposure.get(m.sourceKey)??0)+1);}return {findings:[]};};
 await analyzeXAccount(input);assert.equal(baselineJobs,1);assert.equal(contextJobs,3);for(let i=1;i<20;i++)assert.equal(exposure.get(`post-${i}`),1);assert.equal(exposure.get('post-0'),4);assert.equal(contextExposure.size,6);assert.ok([...contextExposure.values()].every(n=>n===1));assert.match(input.state.analysis.completedBatches[0]!,/^corpus:v4:/);
});
