 input.model=async({purpose,prompt})=>{assert.equal(purpose,'x-account-analyze');const data=dataOf(prompt);if(data.mode==='context'){assert.ok(data.materials.every((m:{sourceKey:string})=>m.sourceKey==='post-1'));windows.push(...data.materials);}return {findings:[]};};await analyzeXAccount(input);assert.deepEqual(windows.map(w=>w.offset),[0,7000,14000]);const covered=new Uint8Array(input.pages[1]!.text.length);for(const w of windows){assert.equal(w.text,input.pages[1]!.text.slice(w.offset,w.offset+w.text.length));covered.fill(1,w.offset,w.offset+w.text.length);}assert.ok(covered.every(value=>value===1));
