test('a useful account report carries measured coverage and unknown history boundaries in every canonical answer',async()=>{
 const input=fixture();input.model=acceptModel();input.state.history.timeline={...input.state.history.timeline,pages:46,done:false,blocked:'empty_history_pages'};await analyzeXAccount(input);
 const report=()=>projectXAccountReport({state:input.state,pages:input.pages,sources:sources(input),activeSourceKeys:new Set(['post-0'])});
 const coverage=report().answer.find(section=>section.id==='x-account-coverage');assert.ok(coverage,'coverage must be in the same canonical report used by UI and exports');assert.match(coverage.body,/46 页/);assert.match(coverage.body,/边界.*未知/);assert.match(coverage.body,/不代表.*完整/);assert.match(coverage.body,/媒体.*未读|未读.*媒体/);
 const withdrawn=projectXAccountReport({state:input.state,pages:input.pages,sources:sources(input),activeSourceKeys:new Set()});assert.equal(withdrawn.answer.length,0,'coverage alone must never masquerade as a useful analysis');
});

function replyAttributionFixture():XAccountAnalysisInput {
 const input=fixture(3);
 input.posts[0]!.kind='reply';input.posts[0]!.parentId='1';input.posts[0]!.text='I use the synthetic editor for drafts.';input.pages[0]!.text=input.posts[0]!.text;
 for(const i of [1,2]){input.posts[i]!.role='parent_context';input.posts[i]!.authorId=`reader-${i}`;input.posts[i]!.authorHandle=`reader_${i}`;input.posts[i]!.text=i===1?'Which editor do you use for drafts?':'I prefer an unrelated synthetic notebook.';input.pages[i]!.text=input.posts[i]!.text;input.pages[i]!.kind='third_party';}
 input.posts[1]!.rootIds=['0'];input.posts[2]!.rootIds=[];
 return input;
}
