 input.state.analysis={completedBatches:[oldSignature],synthesisDone:false,findings:Array.from({length:30},(_,i)=>({id:`batch:legacy-${i}`,section:'work' as const,statement:'这条旧分析尚未按新规则重新核验。',kind:'attributed_statement' as const,verified:true,evidence:[{sourceKey:'post-0',quote:input.pages[0]!.text,quoteOffset:0,sourceContentHash:hash(input.pages[0]!.text)}]}))};
 input.state.gaps=[{code:'analysis_incomplete',target:'research',detail:'Earlier interrupted analysis.'},{code:'provider_billing',target:'context',detail:'Read boundary retained.'},{code:'unknown_inflight',target:'research',detail:'Unknown financial status retained.'}];
