test('a known exhausted analysis protocol leaves its job pending while independent findings continue',async()=>{
 const input=fixture(45);let rejectFirst=true;let analyzeCalls=0;
 input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(purpose.includes('verify'))return{verdicts:data.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'原文支持该自述。'}))};if(purpose==='x-account-analyze'){analyzeCalls++;if(rejectFirst&&data.materials[0].sourceKey==='post-0')throw new DshProtocolRepairExhaustedError('invalid_decision_json',3);}return{findings:[output(data.materials[0].sourceKey)]};};
 await analyzeXAccount(input);assert.equal(analyzeCalls,3);assert.equal(input.state.analysis.completedBatches.filter(k=>k.startsWith('batch:')).length,2);assert.ok(!input.state.analysis.findings.some(f=>f.id.startsWith('report:')));assert.equal(input.state.analysis.synthesisDone,false);assert.equal(input.state.gaps.filter(g=>g.code==='analysis_batch_protocol_unverified').length,1);
 const priorCalls=analyzeCalls;await analyzeXAccount(input);assert.equal(analyzeCalls,priorCalls+1,'the failed job is not marked completed, while successful jobs are retained');assert.equal(input.state.gaps.filter(g=>g.code==='analysis_batch_protocol_unverified').length,1);
 rejectFirst=false;await analyzeXAccount(input);assert.equal(input.state.analysis.completedBatches.filter(k=>k.startsWith('batch:')).length,3);assert.ok(!input.state.gaps.some(g=>g.code==='analysis_batch_protocol_unverified'));assert.equal(input.state.analysis.synthesisDone,true);
});
test('a known exhausted synthesis protocol preserves successful independent synthesis chunks without claiming completion',async()=>{
 const input=fixture(50,5);let synthesisCalls=0;
 input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(purpose.includes('verify'))return{verdicts:data.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'原文支持该自述。'}))};if(purpose==='x-account-analyze')return{findings:data.materials.map((m:{sourceKey:string})=>output(m.sourceKey))};synthesisCalls++;if(synthesisCalls===1)throw new DshProtocolRepairExhaustedError('non_object_decision',3);return{findings:[output(data.materials[0].sourceKey)]};};
 await analyzeXAccount(input);assert.equal(synthesisCalls,5);assert.equal(input.state.analysis.completedBatches.filter(k=>k.startsWith('report:v4:topic:')).length,4);assert.equal(input.state.analysis.findings.filter(f=>f.id.startsWith('report:')).length,4);assert.equal(input.state.analysis.synthesisDone,false);assert.ok(input.state.gaps.some(g=>g.code==='analysis_batch_protocol_unverified'));
});

