test('queued cancellation interrupts completed replay without a new model call or save',async()=>{
 const input=fixture(145);input.model=acceptModel();await analyzeXAccount(input);const markers=[...input.state.analysis.completedBatches];const controller=new AbortController();input.signal=controller.signal;let calls=0,saves=0;input.model=async()=>{calls++;throw Error('unexpected model');};input.save=()=>{saves++;};setImmediate(()=>controller.abort(Error('queued cancellation')));await assert.rejects(analyzeXAccount(input),/queued cancellation/);assert.equal(calls,0);assert.equal(saves,0);assert.deepEqual(input.state.analysis.completedBatches,markers);
});
test('a worker failure during another worker yield prevents the next dispatch',async()=>{
 const input=fixture(85);const pending:Array<{resolve:()=>void;reject:(error:Error)=>void}>=[];let calls=0;input.model=async()=>{calls++;await new Promise<void>((resolve,reject)=>pending.push({resolve,reject}));return{findings:[]};};const running=analyzeXAccount(input);const result=assert.rejects(running,/worker failed/);await new Promise<void>(r=>setImmediate(r));assert.equal(calls,3);pending[1]!.resolve();setImmediate(()=>pending[0]!.reject(Error('worker failed')));await new Promise<void>(r=>setImmediate(r));pending[2]!.resolve();await result;assert.equal(calls,3);
});
