test('report-only guard distinguishes personal blocking from banning and preserves the question',async()=>{
 const text='Are these demo accounts worth banning? I block several accounts each Friday.';
 const correct='该账号询问这些测试账号是否值得封禁，并自述每周屏蔽若干账号。';
 const input=fixture();input.posts[0]!.text=text;input.pages[0]!.text=text;let writes=0;input.model=async({purpose,prompt})=>{const d=dataOf(prompt);if(purpose.includes('verify'))return{verdicts:d.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'Deliberately permissive fixture.'}))};if(d.reportStage==='write')writes++;return{findings:[{...output(),statement:d.reportStage==='write'&&writes===1?'该账号称自己每周封禁一批测试账号。':correct,evidence:[{sourceKey:'post-0',quote:text}]}]};};await analyzeXAccount(input);assert.equal(writes,2);assert.equal(input.state.analysis.synthesisDone,true);const report=input.state.analysis.findings.find(f=>f.id.startsWith('report:v4:'))!;assert.equal(report.statement,correct);
 const project=()=>projectXAccountReport({state:input.state,pages:input.pages,sources:sources(input),activeSourceKeys:new Set(['post-0'])});assert.equal(project().findings.length,1);
 for(const bad of ['该账号询问这些测试账号是否值得封禁并自述每周封禁若干账号。','该账号称自己每周封禁一批测试账号。','该账号表示每周封号若干测试账号。','该账号认为这些测试账号值得封禁，并称自己每周屏蔽若干账号。']){report.statement=bad;const before=JSON.stringify(input.state);const result=project();assert.equal(result.findings.length,0,bad);assert.match(result.limitations.join(' '),/待复核/);assert.equal(JSON.stringify(input.state),before,'forensic original is retained');}
 report.statement=correct.replace('屏蔽','拉黑');assert.equal(project().findings.length,1);report.statement=correct.replace('，并','并');assert.equal(project().findings.length,1);
});
