async function completedInternalLabelFixture(){
 const input=fixture(2,false,false);for(let i=0;i<2;i++){input.posts[i]!.sourceKey=`S${71+i}`;input.pages[i]!.sourceKey=`S${71+i}`;}
 const cache=new Map<string,unknown>(),topicKeys=new Map<string,string>(),seen=new Set<string>();const key=(request:Parameters<XAccountModel>[0])=>JSON.stringify(request);
 input.save=()=>{for(const marker of input.state.analysis.completedBatches)if(marker.startsWith('report:v4:topic:')&&!seen.has(marker)){seen.add(marker);const latest=input.state.analysis.findings.filter(f=>f.id.startsWith('report:v4:')&&f.verified).at(-1)!;topicKeys.set(latest.evidence[0]!.sourceKey,marker);}};
 input.model=async request=>{const d=dataOf(request.prompt);let value:unknown;if(d.organizationStage)value={groups:d.items.map((item:{id:string;sourceKeys:string[]})=>({section:'work',title:item.sourceKeys[0],ids:[item.id]}))};else if(d.reportStage==='select')value={ids:d.items.map((item:{id:string})=>item.id)};else if(request.purpose.includes('verify'))value={verdicts:d.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'Synthetic paid original verdict.'}))};else value={findings:d.reportStage==='write'?[output(d.materials[0].sourceKey)]:d.materials.map((m:{sourceKey:string})=>output(m.sourceKey))};cache.set(key(request),structuredClone(value));return value;};
 await analyzeXAccount(input);assert.equal(input.state.analysis.synthesisDone,true);assert.equal(topicKeys.size,2);
 const stale=input.state.analysis.findings.find(f=>f.id.startsWith('report:v4:')&&f.evidence[0]!.sourceKey==='S71')!;stale.statement='该账号引用 S71 时自述制作了用于比较阅读笔记的工具。';stale.id=stale.id.slice(0,stale.id.lastIndexOf(':')+1)+hash(JSON.stringify([stale.section,stale.statement,stale.kind,stale.evidence])).slice(0,24);
 for(const [request]of cache){const d=dataOf(JSON.parse(request).prompt);if(d.reportStage==='write'&&d.topic.title==='S71')cache.set(request,{findings:[{...output('S71'),statement:stale.statement}]});}
 const corrected={...output('S71'),statement:'该账号自述制作了比较阅读笔记的合成工具。',evidence:[{sourceKey:'S71',quote:input.posts[0]!.text}]};
 return{input,cache,key,topicKeys,stale,corrected};
}

test('current local guards reopen only the affected V4 topic while retaining every other paid input and verdict',async()=>{
 for(const phase of ['complete','partial']){
  const f=await completedInternalLabelFixture();const {input,cache,key,topicKeys,stale,corrected}=f;const old=structuredClone(stale);const unchanged=JSON.stringify(input.state.analysis.findings.filter(finding=>finding.id!==stale.id));const priorMarkers=[...input.state.analysis.completedBatches];
  if(phase==='partial'){input.state.analysis.completedBatches=input.state.analysis.completedBatches.filter(marker=>!marker.startsWith('report:v4:complete:'));input.state.analysis.synthesisDone=false;}
  let writes=0,checks=0,atomic=false,writerReplays=0;
  input.save=()=>{if(!stale.verified&&!atomic){atomic=true;assert.equal(input.state.analysis.synthesisDone,false);assert.ok(!input.state.analysis.completedBatches.some(marker=>marker.startsWith('report:v4:complete:')));assert.ok(!input.state.analysis.completedBatches.includes(topicKeys.get('S71')!));assert.ok(input.state.analysis.completedBatches.includes(topicKeys.get('S72')!));}};
  input.model=async request=>{const d=dataOf(request.prompt);assert.notEqual(request.purpose,'x-account-analyze');if(d.topic)assert.equal(d.topic.title,'S71','the unaffected topic must not call a model again');if(cache.has(key(request))){if(d.reportStage==='write'){writerReplays++;assert.deepEqual(d.rejections,[]);assert.equal(d.attempt,0);}return structuredClone(cache.get(key(request)));}if(request.purpose==='x-account-verify-synthesis'){checks++;assert.ok(atomic,'invalidation must be saved before any new verifier');assert.ok(d.findings.every((finding:{statement:string})=>finding.statement===corrected.statement));return{verdicts:d.findings.map((finding:{id:string})=>({id:finding.id,supported:true,reason:'Fresh independent verdict for the corrected formal quote.'}))};}assert.equal(d.reportStage,'write');writes++;assert.equal(d.attempt,1);assert.equal(d.rejections[0].code,'internal_source_label_in_statement');return{findings:[corrected]};};
  await analyzeXAccount(input);assert.equal(atomic,true,phase);assert.equal(writerReplays,1,phase);assert.equal(writes,1,phase);assert.equal(checks,1,phase);assert.equal(stale.verified,false);assert.deepEqual(stale,{...old,verified:false});assert.equal(input.state.analysis.synthesisDone,true);
  assert.equal(JSON.stringify(input.state.analysis.findings.filter(finding=>finding.id!==stale.id).slice(0,-1)),unchanged,'valid findings and their original verdicts are retained');assert.ok(priorMarkers.filter(marker=>marker!==topicKeys.get('S71')&&!marker.startsWith('report:v4:complete:')).every(marker=>input.state.analysis.completedBatches.includes(marker)));
  const report=projectXAccountReport({state:input.state,pages:input.pages,sources:sources(input),activeSourceKeys:new Set(['S71','S72'])});assert.equal(report.findings.length,2);assert.ok(report.findings.every(finding=>finding.id!==stale.id));assert.ok(report.findings.some(finding=>finding.statement===corrected.statement));
 }
});

test('V4 retirement saves complete removal topic invalidation and diagnostic history together before crash recovery',async()=>{
 const f=await completedInternalLabelFixture();const {input,cache,key,topicKeys,stale,corrected}=f;let persisted:XAccountResearchState|null=null;
 input.model=async request=>{const d=dataOf(request.prompt);assert.ok(d.organizationStage,'only the cached plan may run before retirement is saved');assert.ok(cache.has(key(request)));return structuredClone(cache.get(key(request)));};
 input.save=()=>{persisted=structuredClone(input.state);throw Error('synthetic crash after atomic checkpoint');};
 await assert.rejects(analyzeXAccount(input),/synthetic crash after atomic checkpoint/);assert.ok(persisted);const saved=persisted as XAccountResearchState;assert.equal(saved.analysis.synthesisDone,false);assert.ok(!saved.analysis.completedBatches.some(marker=>marker.startsWith('report:v4:complete:')));assert.ok(!saved.analysis.completedBatches.includes(topicKeys.get('S71')!));assert.ok(saved.analysis.completedBatches.includes(topicKeys.get('S72')!));assert.equal(saved.analysis.findings.find(finding=>finding.id===stale.id)!.verified,false);
 input.state=structuredClone(saved);input.save=()=>{};const project=()=>projectXAccountReport({state:input.state,pages:input.pages,sources:sources(input),activeSourceKeys:new Set(['S71','S72'])});assert.equal(project().findings.length,0,'a restarted process cannot publish the stale complete report');let checks=0;
 input.model=async request=>{const d=dataOf(request.prompt);if(d.topic)assert.equal(d.topic.title,'S71');if(cache.has(key(request)))return structuredClone(cache.get(key(request)));if(request.purpose==='x-account-verify-synthesis'){checks++;return{verdicts:d.findings.map((finding:{id:string})=>({id:finding.id,supported:true,reason:'Independent correction after crash recovery.'}))};}assert.equal(d.reportStage,'write');return{findings:[corrected]};};
 await analyzeXAccount(input);assert.equal(checks,1);assert.equal(input.state.analysis.synthesisDone,true);assert.equal(project().findings.length,2);assert.equal(input.state.analysis.findings.find(finding=>finding.id===stale.id)!.verified,false);
});

test('serial model work still covers every batch planning part merge topic writer and verifier',async()=>{
 const input=fixture(250,false,false);input.modelConcurrency=1;const seen=new Set<string>();const calls=new Map<string,number>();let active=0,peak=0;
 input.model=async({purpose,prompt})=>{const d=dataOf(prompt);const stage=purpose==='x-account-analyze'?'analyze':d.organizationStage??d.reportStage??'verify';calls.set(stage,(calls.get(stage)??0)+1);active++;peak=Math.max(peak,active);
  try{await new Promise<void>(resolve=>setImmediate(resolve));
   if(purpose==='x-account-analyze'){for(const m of d.materials)seen.add(m.sourceKey);return{findings:d.materials.map((m:{sourceKey:string})=>output(m.sourceKey))};}
   if(d.organizationStage==='index')return{groups:d.items.map((item:{id:string})=>({section:'work',title:'合成索引节点',ids:[item.id]}))};
   if(d.organizationStage==='merge'){
    const groups:Array<{section:string;title:string;ids:string[]}>=[];
    if(d.requireConsolidation){for(let i=0;i<d.items.length;i+=2)groups.push({section:'work',title:'合成归并节点',ids:d.items.slice(i,i+2).map((item:{id:string})=>item.id)});}
    else for(let i=0;i<3;i++)groups.push({section:'work',title:`合成主题${i}`,ids:d.items.filter((_item:unknown,index:number)=>index%3===i).map((item:{id:string})=>item.id)});
    return{groups};
   }
   if(d.reportStage==='select')return{ids:[d.items[0].id]};
   if(d.reportStage==='write')return{findings:[output(d.materials[0].sourceKey)]};
   return{verdicts:d.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'Synthetic literal evidence.'}))};
  }finally{active--;}
 };
 await analyzeXAccount(input);assert.equal(peak,1);assert.equal(active,0);assert.equal(seen.size,250,'serial execution does not sample or omit the retained corpus');assert.ok(calls.get('analyze')!>3);assert.ok(calls.get('index')!>1);assert.ok(calls.get('merge')!>1);assert.ok(calls.get('select')!>=3);assert.equal(calls.get('write'),3);assert.equal(calls.get('verify'),3);assert.equal(input.state.analysis.synthesisDone,true);
});

test('serial model failure drains its only worker and never starts another queued batch',async()=>{
 const input=fixture(85);input.modelConcurrency=1;const pending:Array<(error:Error)=>void>=[];let calls=0,active=0,saves=0;input.save=()=>{saves++;};
 input.model=async()=>{calls++;active++;try{await new Promise<void>((_resolve,reject)=>pending.push(reject));return{findings:[]};}finally{active--;}};
 const running=analyzeXAccount(input);const rejected=assert.rejects(running,/serial model failure/);await until(()=>pending.length>0);const started=calls;for(const reject of pending)reject(Error('serial model failure'));await rejected;
 assert.equal(started,1);assert.equal(calls,1);assert.equal(active,0);assert.equal(input.state.analysis.completedBatches.filter(key=>key.startsWith('batch:')).length,0);const saved=saves;await new Promise<void>(resolve=>setImmediate(resolve));assert.equal(calls,1);assert.equal(saves,saved,'all work has drained before returning the failure');
});

test('final synthesis narrows unsupported corpus availability counterevidence and personal relationships through bounded revision',async()=>{
 for(const scenario of ['corpus','counterevidence','relationship']){
  const input=scenario==='counterevidence'?replyAttributionFixture():fixture(scenario==='corpus'?2:1);let writes=0,checks=0;
  const constrained=(instruction:string)=>scenario==='corpus'?instruction.includes('全语料')&&instruction.includes('窗口外'):scenario==='counterevidence'?instruction.includes('可比条件')&&instruction.includes('同一提示词'):instruction.includes('显式关系称谓')&&instruction.includes('赠送');
  let good:ReturnType<typeof output>,bad:ReturnType<typeof output>;
  if(scenario==='corpus'){good={...output(),kind:'inference',statement:'所引两条帖子分别发表于2025年1月1日和1月2日，均介绍了比较阅读笔记的工具。',evidence:[output('post-0').evidence[0]!,output('post-1').evidence[0]!]};bad={...good,statement:'所引两条帖文界定了本主题的日期范围，窗口外的历史与后续情况在全部现有语料中不可得。'};}
  else if(scenario==='counterevidence'){input.posts[0]!.text='The helper completed my test on one website.';input.posts[1]!.text='The helper was blocked on a different website.';for(const i of [0,1])input.pages[i]!.text=input.posts[i]!.text;good={...output(),section:'interaction',kind:'page_statement',statement:'该账号自述助手完成了测试；关联回复者称另一个网站受阻，所引原文未说明是否使用同一提示词及相同网站条件。',evidence:[{sourceKey:'post-0',quote:input.posts[0]!.text,quoteOffset:0},{sourceKey:'post-1',quote:input.posts[1]!.text,quoteOffset:0}]};bad={...good,statement:'关联回复者称另一个网站受阻，构成对同一提示词有效性的相反证据。'};}
  else{input.posts[0]!.text='Thank you Sam for sending me this free sample.';input.pages[0]!.text=input.posts[0]!.text;good={...output(),statement:'该账号感谢 Sam 寄来免费样品。',evidence:[{sourceKey:'post-0',quote:input.posts[0]!.text,quoteOffset:0}]};bad={...good,statement:'该账号感谢朋友 Sam 寄来免费样品。'};}
  input.model=async({purpose,prompt})=>{const d=dataOf(prompt),instruction=prompt.slice(0,prompt.indexOf('\nDATA\n'));if(purpose==='x-account-verify-synthesis'){checks++;const strict=constrained(instruction);return{verdicts:d.findings.map((finding:{id:string;statement:string})=>({id:finding.id,supported:!strict||finding.statement!==bad.statement,reason:'正式引文未支持该可用性、可比条件或关系判断，须收回额外结论。'}))};}if(d.reportStage==='write'){writes++;assert.equal(constrained(instruction),false,'final-only verification rules must not change the writer request');if(writes>1)assert.ok(d.rejections.some((r:{reason:string})=>r.reason.includes('须收回额外结论')));return{findings:[writes===1?bad:good]};}assert.equal(constrained(instruction),false,'reading and planning identities must not receive final-only rules');return{findings:[good]};};
  await analyzeXAccount(input);assert.equal(writes,2,scenario);assert.equal(checks,2,scenario);assert.equal(input.state.analysis.synthesisDone,true);const report=projectXAccountReport({state:input.state,pages:input.pages,sources:sources(input),activeSourceKeys:new Set(input.pages.map(page=>page.sourceKey))});assert.equal(report.findings.length,1);assert.equal(report.findings[0]!.statement,good.statement);
 }
});

test('an exact retired V4 finding returns to publication only after a fresh successful independent verdict',async()=>{
 for(const verdict of ['accept','reject','transport']){
  const {input,cache,key,topicKeys,stale}=await completedInternalLabelFixture();stale.statement=output('S71').statement;stale.id=stale.id.slice(0,stale.id.lastIndexOf(':')+1)+hash(JSON.stringify([stale.section,stale.statement,stale.kind,stale.evidence])).slice(0,24);stale.verified=false;
  for(const [request]of cache){const d=dataOf(JSON.parse(request).prompt);if(d.reportStage==='write'&&d.topic.title==='S71')cache.set(request,{findings:[output('S71')]});}
  for(const [request,value]of [...cache]){const old=JSON.parse(request) as Parameters<XAccountModel>[0];if(old.purpose!=='x-account-verify-synthesis')continue;const extra=old.prompt.indexOf('\n最终综合补充边界：'),data=old.prompt.indexOf('\nDATA\n');if(extra>=0){old.prompt=old.prompt.slice(0,extra)+old.prompt.slice(data);cache.delete(request);cache.set(key(old),value);}}
  input.state.analysis.completedBatches=input.state.analysis.completedBatches.filter(marker=>!marker.startsWith('report:v4:complete:')&&marker!==topicKeys.get('S71'));input.state.analysis.synthesisDone=false;input.save=()=>{};
  const retired=structuredClone(stale),receipts=JSON.stringify([...cache]);const unaffected=input.state.analysis.findings.find(finding=>finding.id.startsWith('report:v4:')&&finding.evidence[0]!.sourceKey==='S72')!;const unchanged=JSON.stringify(unaffected);let checks=0;
  input.model=async request=>{const d=dataOf(request.prompt);assert.notEqual(request.purpose,'x-account-analyze');if(d.topic)assert.equal(d.topic.title,'S71','other completed topics do not run again');if(request.purpose==='x-account-verify-synthesis'){checks++;assert.equal(stale.verified,false,'replay alone cannot restore the retired judgment');assert.equal(d.findings[0].id,stale.id);assert.equal(cache.has(key(request)),false,'the stricter final verifier cannot reuse the old semantic verdict');if(verdict==='transport')throw Error('synthetic verifier transport failure');return{verdicts:d.findings.map((finding:{id:string})=>({id:finding.id,supported:verdict==='accept',reason:'Independent review under the current final-only evidence constraints.'}))};}if(cache.has(key(request)))return structuredClone(cache.get(key(request)));assert.equal(d.reportStage,'write');return{findings:[output('S71')]};};
  if(verdict==='transport')await assert.rejects(analyzeXAccount(input),/synthetic verifier transport failure/);else await analyzeXAccount(input);
  assert.equal(checks,verdict==='reject'?3:1);assert.deepEqual(stale,{...retired,verified:verdict==='accept'});assert.equal(input.state.analysis.findings.filter(finding=>finding.id===stale.id).length,1,'reverification must not duplicate the same finding');assert.equal(JSON.stringify(unaffected),unchanged);assert.equal(JSON.stringify([...cache]),receipts,'historical writer and verifier receipts remain unchanged');assert.equal(input.state.analysis.synthesisDone,verdict==='accept');
  const report=projectXAccountReport({state:input.state,pages:input.pages,sources:sources(input),activeSourceKeys:new Set(['S71','S72'])});assert.equal(report.findings.length,verdict==='accept'?2:0);if(verdict==='accept')assert.ok(report.findings.some(finding=>finding.id===stale.id));
 }
});

test('a review rejection retires only its exact V4 topic atomically and prevents the same evidence combination from returning',async()=>{
 for(const result of ['repair','repeat']){
  const {input,cache,key,topicKeys,stale,corrected}=await completedInternalLabelFixture();stale.statement='该账号自述制作了能提高所有读者效率的合成工具。';stale.id=stale.id.slice(0,stale.id.lastIndexOf(':')+1)+hash(JSON.stringify([stale.section,stale.statement,stale.kind,stale.evidence])).slice(0,24);
  const bad={...output('S71'),statement:stale.statement};for(const [request]of cache){const d=dataOf(JSON.parse(request).prompt);if(d.reportStage==='write'&&d.topic.title==='S71')cache.set(request,{findings:[bad]});}
  const marker=`report:v4:review-reject:${stale.id.split(':')[2]}:${stale.id.split(':').at(-1)}`;input.state.analysis.completedBatches.push(marker);const old=structuredClone(stale),receipts=JSON.stringify([...cache]);let retired=false,writes=0,checks=0,replays=0;
  assert.equal(stale.verified,true);assert.equal(input.state.analysis.synthesisDone,true);assert.ok(input.state.analysis.completedBatches.includes(topicKeys.get('S71')!));assert.ok(input.state.analysis.completedBatches.some(k=>k.startsWith('report:v4:complete:')));
  const project=()=>projectXAccountReport({state:input.state,pages:input.pages,sources:sources(input),activeSourceKeys:new Set(['S71','S72'])});assert.ok(!project().findings.some(finding=>finding.id===stale.id),'canonical publication respects a newly recorded review rejection before retirement runs');
  input.save=()=>{if(!stale.verified&&!retired){retired=true;assert.ok(!input.state.analysis.completedBatches.some(k=>k.startsWith('report:v4:complete:')));assert.ok(!input.state.analysis.completedBatches.includes(topicKeys.get('S71')!));assert.ok(input.state.analysis.completedBatches.includes(topicKeys.get('S72')!));assert.ok(input.state.analysis.completedBatches.includes(marker));assert.equal(input.state.analysis.synthesisDone,false);}};
  input.model=async request=>{const d=dataOf(request.prompt);assert.notEqual(request.purpose,'x-account-analyze');if(d.topic)assert.equal(d.topic.title,'S71');if(cache.has(key(request))){if(d.reportStage==='write'){replays++;assert.deepEqual(d.rejections,[]);assert.ok(retired,'retirement must be durable before replaying the old writer');}return structuredClone(cache.get(key(request)));}if(request.purpose==='x-account-verify-synthesis'){checks++;assert.ok(d.findings.every((finding:{id:string})=>finding.id.split(':').at(-1)!==stale.id.split(':').at(-1)),'an old approved verdict cannot override the review rejection');return{verdicts:d.findings.map((finding:{id:string})=>({id:finding.id,supported:true,reason:'Independent approval of the corrected literal claim.'}))};}assert.equal(d.reportStage,'write');writes++;assert.equal(d.rejections.length,1);assert.equal(d.rejections[0].statement,stale.statement);assert.match(d.rejections[0].reason,/审阅.*(?:否决|拒绝)/);return{findings:[result==='repair'?corrected:bad]};};
  await analyzeXAccount(input);assert.equal(retired,true);assert.equal(replays,1);assert.equal(writes,result==='repair'?1:2);assert.equal(checks,result==='repair'?1:0);assert.deepEqual(stale,{...old,verified:false});assert.equal(input.state.analysis.synthesisDone,result==='repair');assert.equal(project().findings.length,result==='repair'?2:0);assert.ok(input.state.analysis.completedBatches.includes(marker));assert.equal(JSON.stringify([...cache]),receipts);
  if(result==='repair'){const completed=JSON.stringify(input.state);input.model=async()=>{throw Error('completed corrected topics must not be bought again');};await analyzeXAccount(input);assert.equal(JSON.stringify(input.state),completed);}
 }
});

test('a review rejection for another V4 plan or statement evidence hash does not reopen valid topics',async()=>{
 for(const mismatch of ['plan','hash']){
  const {input,stale}=await completedInternalLabelFixture();stale.statement=output('S71').statement;stale.id=stale.id.slice(0,stale.id.lastIndexOf(':')+1)+hash(JSON.stringify([stale.section,stale.statement,stale.kind,stale.evidence])).slice(0,24);
  input.state.analysis.completedBatches.push(`report:v4:review-reject:${mismatch==='plan'?'f'.repeat(64):stale.id.split(':')[2]}:${mismatch==='hash'?'e'.repeat(24):stale.id.split(':').at(-1)}`);const before=JSON.stringify(input.state);input.model=async()=>{throw Error('unrelated review markers must not cause model work');};input.save=()=>{throw Error('unrelated review markers must not rewrite the checkpoint');};
  await analyzeXAccount(input);assert.equal(JSON.stringify(input.state),before,mismatch);assert.equal(projectXAccountReport({state:input.state,pages:input.pages,sources:sources(input),activeSourceKeys:new Set(['S71','S72'])}).findings.length,2,mismatch);
 }
});

test('review rejection retires the whole affected topic and restores only findings approved under the new verifier',async()=>{
 for(const verdict of ['accept','reject','transport']){
  const {input,cache,key,topicKeys,stale}=await completedInternalLabelFixture();const prefix=stale.id.split(':').slice(0,4).join(':');stale.statement='该账号自述制作了能提高所有读者效率的合成工具。';stale.id=`${prefix}:0001:${hash(JSON.stringify([stale.section,stale.statement,stale.kind,stale.evidence])).slice(0,24)}`;
  const companion={...structuredClone(stale),statement:'该账号自述制作了比较阅读笔记的合成工具。',evidence:[{sourceKey:'S71',quote:input.posts[0]!.text,quoteOffset:0,sourceContentHash:hash(input.posts[0]!.text)}]};companion.id=`${prefix}:0000:${hash(JSON.stringify([companion.section,companion.statement,companion.kind,companion.evidence])).slice(0,24)}`;input.state.analysis.findings.push(companion);
  const rawCompanion={...output('S71'),statement:companion.statement,evidence:[{sourceKey:'S71',quote:input.posts[0]!.text,quoteOffset:0}]},rawBad={...output('S71'),statement:stale.statement};
  for(const [request]of cache){const d=dataOf(JSON.parse(request).prompt);if(d.reportStage==='write'&&d.topic.title==='S71')cache.set(request,{findings:[rawCompanion,rawBad]});}
  const marker=`report:v4:review-reject:${stale.id.split(':')[2]}:${stale.id.split(':').at(-1)}`;input.state.analysis.completedBatches.push(marker);let checks=0,atomic=false;const other=input.state.analysis.findings.find(finding=>finding.id.startsWith('report:v4:')&&finding.evidence[0]!.sourceKey==='S72')!;const unchanged=JSON.stringify(other);
  input.save=()=>{if(!stale.verified&&!atomic){atomic=true;assert.equal(companion.verified,false,'all old findings in the affected topic retire in the same checkpoint');assert.ok(!input.state.analysis.completedBatches.some(m=>m.startsWith('report:v4:complete:')));assert.ok(!input.state.analysis.completedBatches.includes(topicKeys.get('S71')!));assert.ok(input.state.analysis.completedBatches.includes(topicKeys.get('S72')!));assert.ok(input.state.analysis.completedBatches.includes(marker));}};
  input.model=async request=>{const d=dataOf(request.prompt);assert.notEqual(request.purpose,'x-account-analyze');if(d.topic)assert.equal(d.topic.title,'S71');if(request.purpose==='x-account-verify-synthesis'){checks++;assert.ok(atomic);assert.equal(stale.verified,false);assert.equal(companion.verified,false,'the old approval cannot survive before a new verdict');assert.equal(d.findings.length,1);assert.equal(d.findings[0].id,companion.id);if(verdict==='transport')throw Error('synthetic strict verifier failure');return{verdicts:[{id:companion.id,supported:verdict==='accept',reason:'Current independent verdict for the remaining literal claim.'}]};}if(cache.has(key(request)))return structuredClone(cache.get(key(request)));assert.equal(d.reportStage,'write');return{findings:[rawCompanion,rawBad]};};
  if(verdict==='transport')await assert.rejects(analyzeXAccount(input),/synthetic strict verifier failure/);else await analyzeXAccount(input);
  assert.equal(atomic,true);assert.equal(checks,verdict==='reject'?3:1);assert.equal(stale.verified,false);assert.equal(companion.verified,verdict==='accept');assert.equal(input.state.analysis.findings.filter(finding=>finding.id===companion.id).length,1);assert.equal(JSON.stringify(other),unchanged);assert.equal(input.state.analysis.synthesisDone,verdict==='accept');assert.ok(input.state.analysis.completedBatches.includes(marker));const report=projectXAccountReport({state:input.state,pages:input.pages,sources:sources(input),activeSourceKeys:new Set(['S71','S72'])});assert.equal(report.findings.length,verdict==='accept'?2:0);assert.ok(report.findings.every(finding=>finding.id!==stale.id));
 }
});
